// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.security.diimport android.content.Contextimport androidx.work.ExistingPeriodicWorkPolicyimport androidx.work.PeriodicWorkRequestBuilderimport com.roshan.persona.di.AppInitializerimport com.roshan.persona.di.Priorityimport com.roshan.persona.security.supplychain.SupplyChainMonitorimport com.roshan.persona.security.supplychain.SupplyChainScanWorkerimport timber.log.Timberimport java.util.concurrent.TimeUnitimport javax.inject.Injectimport javax.inject.Singleton/** * NOUS — Security Initializer (Module 12, Defense Layer 1 wiring). * * Strategy §12.7 — runs at app boot to: * *   1. Perform an immediate supply-chain scan synchronously so the cached *      [com.roshan.persona.security.supplychain.ScanResult] is warm before *      any credential vault / backup operation can run. *   2. Schedule [SupplyChainScanWorker] as a 10-minute periodic WorkManager *      job so the cache is refreshed in the background while the app is alive. * * ## Priority * * [Priority.NORMAL] — runs AFTER [com.roshan.persona.init.DatabaseInitializer] * (CRITICAL) so the security Room DB (which holds the PIN hash) is open. Not * blocking — we don't want a transient WorkManager init failure to halt * the app boot; the credential vault lazily scans on first access. * * ## Idempotency * * [ExistingPeriodicWorkPolicy.KEEP] means: if a previous app launch already * scheduled the worker, we don't replace it. This avoids duplicate workers * piling up across launches. * * ## Real Android APIs used * * | Operation | API | * |-----------|-----| * | Periodic schedule | `WorkManager.enqueueUniquePeriodicWork(name, KEEP, request)` | * | Repeat interval | `PeriodicWorkRequestBuilder<SupplyChainScanWorker>(10, TimeUnit.MINUTES)` | * | App boot hook | [AppInitializer.initialize] called by [com.roshan.persona.di.AppInitializers] | * * @see SupplyChainScanWorker * @see SupplyChainMonitor */@Singletonclass SecurityInitializer @Inject constructor(    private val supplyChainMonitor: SupplyChainMonitor,) : AppInitializer {    override val priority: Priority = Priority.NORMAL    override val isBlocking: Boolean = false    override fun initialize(context: Context) {        // ─── 1. Immediate scan (synchronous, ~5–20 ms) ───────────────────        // This populates the cached scan in CredentialVaultImpl / BackupRestoreManager        // on first access — but we run it here so the result is ready BEFORE        // any UI flow needs it.        try {            val scan = supplyChainMonitor.scan()            Timber.tag("NOUS.Security").i(                "Boot-time supply chain scan: state=%s, threats=%d, durationMs=%d",                scan.state, scan.threats.size, scan.durationMs,            )        } catch (e: Exception) {            Timber.tag("NOUS.Security").e(e, "Boot-time supply chain scan failed (non-fatal)")        }        // ─── 2. Schedule periodic 10-minute WorkManager scan ─────────────        try {            val request = PeriodicWorkRequestBuilder<SupplyChainScanWorker>(                SupplyChainScanWorker.REPEAT_INTERVAL_MINUTES, TimeUnit.MINUTES,            ).build()            androidx.work.WorkManager.getInstance(context).enqueueUniquePeriodicWork(                SupplyChainScanWorker.WORK_NAME,                ExistingPeriodicWorkPolicy.KEEP,                request,            )            Timber.tag("NOUS.Security").i(                "Scheduled periodic supply chain scan (every %d min)",                SupplyChainScanWorker.REPEAT_INTERVAL_MINUTES,            )        } catch (e: Exception) {            Timber.tag("NOUS.Security").e(e, "Failed to schedule SupplyChainScanWorker (non-fatal)")        }    }}